#!/usr/bin/env node
/**
 * Bundles `src/browser-entry.ts` into a single JS string that the native app
 * injects into its scraping WebViews.
 *
 *   node scripts/build-browser-bundle.mjs           # write the bundle
 *   node scripts/build-browser-bundle.mjs --check   # fail if it is stale
 *
 * The generated file is committed so Metro and EAS never need this step.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(here, "..");
const entryPoint = resolve(packageRoot, "src/browser-entry.ts");
const outputFile = resolve(
  packageRoot,
  "../../apps/native/lib/scraper/extractor-bundle.generated.ts",
);

const result = await build({
  entryPoints: [entryPoint],
  bundle: true,
  write: false,
  format: "iife",
  target: ["es2019"],
  platform: "browser",
  minify: true,
  legalComments: "none",
  charset: "utf8",
});

const code = result.outputFiles[0].text.trim();
const contents = `// AUTO-GENERATED by packages/scraper-core/scripts/build-browser-bundle.mjs
// Source: packages/scraper-core/src/browser-entry.ts — do not edit by hand.
// Regenerate with: pnpm --filter @wishlist/scraper-core build:bundle
/* eslint-disable */
export const EXTRACTOR_JS = ${JSON.stringify(code)};
`;

if (process.argv.includes("--check")) {
  let existing = "";
  try {
    existing = await readFile(outputFile, "utf8");
  } catch {
    existing = "";
  }
  if (existing !== contents) {
    console.error(
      "extractor-bundle.generated.ts is out of date. Run: pnpm --filter @wishlist/scraper-core build:bundle",
    );
    process.exit(1);
  }
  console.log("extractor bundle is up to date");
} else {
  await mkdir(dirname(outputFile), { recursive: true });
  await writeFile(outputFile, contents, "utf8");
  console.log(`wrote ${outputFile} (${(code.length / 1024).toFixed(1)} KiB of JS)`);
}
